'use client';

import { Info } from 'lucide-react';

export function WelcomeBanner() {
  return (
    <div className="fixed top-0 left-0 right-0 z-50 bg-brand-light-blue border-b border-blue-200 p-4 shadow-sm">
      <div className="mx-auto max-w-4xl px-6">
        <div className="flex items-start gap-3">
          <Info className="h-5 w-5 text-blue-600 mt-0.5 flex-shrink-0" />
          <div className="text-sm text-blue-800 leading-relaxed text-justify">
            <strong>Welcome!</strong> This is your personalized Handld quote, created specifically for your home. It covers services for the next 12 months, and you can easily add or remove items or adjust service frequencies to fit your needs. When you sign up for 3 or more services, you&apos;ll unlock Handld Membership—saving you hundreds of dollars and up to 30% off every service.
          </div>
        </div>
      </div>
    </div>
  );
}

