'use client';

import Image from 'next/image';

interface LogoProps {
  /** Width and height of the logo in pixels */
  size?: 64 | 80 | 96 | 128;
  className?: string;
}

export function Logo({ size = 64, className = "" }: LogoProps) {
  return (
    <Image
      src="/logo.png"
      alt="Handld"
      width={size}
      height={size}
      className={`object-contain ${className}`}
      priority
