            {quote.quoteId && (
              <div className="text-xs md:text-sm text-brand-navy">
                Quote ID: {quote.quoteId}
              </div>
            )}
          </div>
        </div>
      </header>


      {/* Customer Information - Condensed */}
      <section className="mb-4">
        <div className="border border-gray-200 rounded-xl p-3 bg-brand-light-cream shadow-md overflow-hidden">
