                </div>
                <div className="text-base text-brand-navy">
                  {quote.lotSize}
                </div>
              </div>
            )}
          </div>
        </div>
      </section>


      {/* Services */}
      <section className="mb-4">
        <div className="flex items-center justify-between mb-3">
          <h2 className="text-xl md:text-2xl font-bold text-brand-navy">Services</h2>
          <button
            onClick={() => setIsServiceModalOpen(true)}
            className="text-xs md:text-sm px-3 md:px-4 py-2 rounded-full border border-brand-navy text-brand-navy bg-brand-light-blue hover:bg-brand-cream transition-all duration-300 flex items-center gap-1"
          >
            <Plus className="h-3 w-3 md:h-4 md:w-4" />
            <span className="hidden sm:inline">Add Service</span>
            <span className="sm:hidden">Add</span>
          </button>
        </div>
        <div className="shadow-md rounded-xl overflow-hidden">
          <LineItemsTable 
            lineItems={lineItems}
            loadingItems={loadingItems} 
            onFrequencyChange={handleFrequencyChange}
            onRemoveItem={handleDeleteItem}
            membershipAvailable={membershipAvailable}
          />
        </div>
      </section>

      {/* Buttons */}
      <section className="space-y-4">
        {/* Savings Highlight or CTA */}
        {membershipAvailable && savings > 0 ? (
          <div className="relative overflow-hidden bg-gradient-to-r from-green-400 via-emerald-400 to-teal-400 rounded-xl p-4 md:p-5 shadow-xl">
            <div className="absolute inset-0 bg-gradient-to-r from-green-400/20 via-emerald-400/20 to-teal-400/20 animate-pulse"></div>
            <div className="relative flex flex-col sm:flex-row items-center sm:justify-between">
              <div className="flex items-center gap-3 md:gap-4">
                <Trophy className="h-6 w-6 md:h-8 md:w-8 text-white filter drop-shadow-md" />
                <div className="text-center sm:text-left">
                  <p className="font-bold text-base md:text-xl text-white drop-shadow-md">Your Handld Member Savings: {fmtMoney(savings)}!</p>
                  <p className="text-xs md:text-sm text-white/90 mt-1">Lock in these savings with Handld Membership!</p>
                </div>
              </div>
            </div>
          </div>
        ) : !membershipAvailable && (
          <CTABanner message={`Add ${servicesNeeded} more service${servicesNeeded === 1 ? '' : 's'} to unlock Handld Membership and save 30%!`} />
        )}

        <div className="flex flex-col gap-3 md:gap-4">
          <button
            onClick={handleMemberBooking}
            disabled={!membershipAvailable}
            className={`w-full rounded-full py-3 md:py-4 px-4 md:px-8 text-sm md:text-lg font-semibold transition-all duration-200 shadow-lg ${
              membershipAvailable
                ? 'text-white bg-brand-navy hover:bg-opacity-90 cursor-pointer'
                : 'text-gray-400 bg-gray-200 cursor-not-allowed opacity-60'
            }`}
          >
            <span className="hidden md:inline">
              {membershipAvailable ? (savings > 0 ? `Book Handld Membership — Save ${fmtMoney(savings)}` : 'Book Handld Membership — Save 30%') : 'Membership requires 3+ services'}
            </span>
            <span className="md:hidden">
              {membershipAvailable ? (savings > 0 ? `Member — Save ${fmtMoney(savings)}` : 'Member — Save 30%') : 'Need 3+ services'}
            </span>
          </button>
          <button
            onClick={handleAlaCarteBooking}
            disabled={alaCarteTotal === 0}
            className={`w-full rounded-full py-3 md:py-4 px-4 md:px-8 text-sm md:text-lg font-medium border-2 transition-all duration-200 ${
              alaCarteTotal > 0
                ? 'border-brand-navy text-brand-navy bg-brand-light-blue hover:bg-brand-cream cursor-pointer'
                : 'border-gray-300 text-gray-400 bg-gray-100 cursor-not-allowed opacity-60'
            }`}
          >
            <span className="hidden md:inline">
              {alaCarteTotal > 0 ? `Book with Standard Pricing — ${fmtMoney(alaCarteTotal)}` : 'Select services to book'}
            </span>
            <span className="md:hidden">
              {alaCarteTotal > 0 ? `Standard — ${fmtMoney(alaCarteTotal)}` : 'Select services'}
            </span>
          </button>
        </div>
      </section>

      {/* Confirmation Dialog */}
      <ConfirmationDialog
        isOpen={deleteConfirmation.isOpen}
        title="Remove Service"
        message={`Are you sure you want to remove "${deleteConfirmation.serviceName}" from your quote? This action cannot be undone.`}
        confirmLabel="Remove"
        cancelLabel="Cancel"
        variant="danger"
        onConfirm={confirmDelete}
        onCancel={() => setDeleteConfirmation({ isOpen: false, itemId: '', serviceName: '' })}
      />

      {/* Service Selection Modal */}
      <ServiceSelectionModal
        isOpen={isServiceModalOpen}
        onClose={() => setIsServiceModalOpen(false)}
        onSelectService={handleAddService}
        services={services}
        isLoading={servicesLoading}
        error={servicesError}
        isAddingService={isAdding}
      />
        </div>
      </main>
    </div>
  );
}

