import React from 'react';
import { render, screen, fireEvent, waitFor } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import LineItemsTable from '../LineItemsTable';
import type { LineItem } from '@/lib/airtable';

// Mock lucide-react
jest.mock('lucide-react', () => ({
  Loader2: ({ className }: { className?: string }) => (
    <div data-testid="loader" className={className}>Loading...</div>
  ),
  Droplets: ({ className }: { className?: string }) => (
    <div data-testid="droplets-icon" className={className}>💧</div>
  ),
  Sparkles: ({ className }: { className?: string }) => (
    <div data-testid="sparkles-icon" className={className}>✨</div>
  ),
  Scissors: ({ className }: { className?: string }) => (
    <div data-testid="scissors-icon" className={className}>✂️</div>
  ),
  Waves: ({ className }: { className?: string }) => (
    <div data-testid="waves-icon" className={className}>🌊</div>
  ),
  Wrench: ({ className }: { className?: string }) => (
    <div data-testid="wrench-icon" className={className}>🔧</div>
  ),
  TreePine: ({ className }: { className?: string }) => (
    <div data-testid="tree-icon" className={className}>🌲</div>
  ),
  Hammer: ({ className }: { className?: string }) => (
    <div data-testid="hammer-icon" className={className}>🔨</div>
  ),
  Car: ({ className }: { className?: string }) => (
    <div data-testid="car-icon" className={className}>🚗</div>
  ),
  Home: ({ className }: { className?: string }) => (
    <div data-testid="home-icon" className={className}>🏠</div>
  ),
  Leaf: ({ className }: { className?: string }) => (
    <div data-testid="leaf-icon" className={className}>🍃</div>
  ),
  Shovel: ({ className }: { className?: string }) => (
    <div data-testid="shovel-icon" className={className}>🔨</div>
  ),
  Zap: ({ className }: { className?: string }) => (
    <div data-testid="zap-icon" className={className}>⚡</div>
  ),
}));

describe('LineItemsTable', () => {
  const mockLineItems: LineItem[] = [
    {
      id: 'rec1',
      service: 'Lawn Mowing',
      alaCarteRate: 100,
      handldRate: 70,
      chosenFrequency: 2,
      quoteId: 'Q-001',
    },
    {
      id: 'rec2',
      service: 'Pool Cleaning',
      alaCarteRate: 150,
      handldRate: 105,
      chosenFrequency: undefined,
      quoteId: 'Q-001',
    },
  ];

  const mockOnFrequencyChange = jest.fn();
  const mockOnRemoveItem = jest.fn();

  beforeEach(() => {
    jest.clearAllMocks();
  });

  it('renders nothing when lineItems is empty', () => {
    const { container } = render(
      <LineItemsTable lineItems={[]} />
    );
    expect(container.firstChild).toBeNull();
  });

  it('renders line items correctly', () => {
    render(
      <LineItemsTable 
        lineItems={mockLineItems}
        onFrequencyChange={mockOnFrequencyChange}
        onRemoveItem={mockOnRemoveItem}
      />
    );

    // Check headers
    expect(screen.getByText('Service')).toBeInTheDocument();
    expect(screen.getByText('Frequency')).toBeInTheDocument();
    expect(screen.getByText('Standard Price')).toBeInTheDocument();
    expect(screen.getByText('Member Price')).toBeInTheDocument();

    // Check service names (both mobile and desktop layouts render)
    expect(screen.getAllByText('Lawn Mowing').length).toBeGreaterThan(0);
    expect(screen.getAllByText('Pool Cleaning').length).toBeGreaterThan(0);

    // Check prices (both mobile and desktop layouts render)
    expect(screen.getAllByText('$100').length).toBeGreaterThan(0);
    expect(screen.getAllByText('$70').length).toBeGreaterThan(0);
    expect(screen.getAllByText('$150').length).toBeGreaterThan(0);
    expect(screen.getAllByText('$105').length).toBeGreaterThan(0);
  });

  it('displays correct frequency values in dropdowns', () => {
    render(
      <LineItemsTable 
        lineItems={mockLineItems}
        onFrequencyChange={mockOnFrequencyChange}
      />
    );

    const dropdowns = screen.getAllByRole('combobox');

    // Both mobile and desktop dropdowns are rendered, so we have doubles
    // Check first item's dropdowns (indices 0 and 2 for mobile/desktop)
    expect(dropdowns[0]).toHaveValue('2');
    expect(dropdowns[2]).toHaveValue('2');

    // Check second item's dropdowns (indices 1 and 3)
    expect(dropdowns[1]).toHaveValue('1');
    expect(dropdowns[3]).toHaveValue('1');
  });

  it('calls onFrequencyChange when frequency is changed', async () => {
    const user = userEvent.setup();

    render(
      <LineItemsTable 
        lineItems={mockLineItems}
        onFrequencyChange={mockOnFrequencyChange}
      />
    );

    const dropdowns = screen.getAllByRole('combobox');

    // Change frequency of first item (use first dropdown)
    await user.selectOptions(dropdowns[0], '4');

    expect(mockOnFrequencyChange).toHaveBeenCalledWith('rec1', 4);
  });

  it('calls onRemoveItem when remove button is clicked', async () => {
    const user = userEvent.setup();

    render(
      <LineItemsTable 
        lineItems={mockLineItems}
        onFrequencyChange={mockOnFrequencyChange}
        onRemoveItem={mockOnRemoveItem}
      />
    );

    const removeButtons = screen.getAllByText('Remove');

    // Click remove on first item
    await user.click(removeButtons[0]);

    expect(mockOnRemoveItem).toHaveBeenCalledWith('rec1');
  });

  it('shows alert when handlers are not provided', async () => {
    const alertSpy = jest.spyOn(window, 'alert').mockImplementation(() => {});
    const user = userEvent.setup();

    render(
      <LineItemsTable lineItems={mockLineItems} />
    );

    const dropdowns = screen.getAllByRole('combobox');
    await user.selectOptions(dropdowns[0], '3');

    expect(alertSpy).toHaveBeenCalledWith('TODO: Update Lawn Mowing frequency to 3');

    alertSpy.mockRestore();
  });

  it('shows loading state for items being updated', () => {
    const loadingItems = new Set(['rec1']);

    render(
      <LineItemsTable 
        lineItems={mockLineItems}
        loadingItems={loadingItems}
        onFrequencyChange={mockOnFrequencyChange}
      />
    );

    // Check for loader on first item
    const loader = screen.getByTestId('loader');
    expect(loader).toBeInTheDocument();
    expect(loader).toHaveClass('animate-spin');

    // Check that dropdown is disabled for loading item
    const dropdowns = screen.getAllByRole('combobox');
    expect(dropdowns[0]).toBeDisabled();
    expect(dropdowns[1]).not.toBeDisabled();

    // Check that remove button is disabled for loading item
    const removeButtons = screen.getAllByText('Remove');
    expect(removeButtons[0]).toBeDisabled();
    expect(removeButtons[1]).not.toBeDisabled();
  });

  it('applies correct styling when item is loading', () => {
    const loadingItems = new Set(['rec1']);

    const { container } = render(
      <LineItemsTable 
        lineItems={mockLineItems}
        loadingItems={loadingItems}
        onFrequencyChange={mockOnFrequencyChange}
      />
    );

    // Find the row containers by looking for elements with p-4 class (our row styling)
    const rows = container.querySelectorAll('.p-4.bg-brand-light-blue');

    // First row should have opacity class
    expect(rows[0]).toHaveClass('opacity-60');

    // Second row should not have opacity class
    expect(rows[1]).not.toHaveClass('opacity-60');
  });

  it('handles all frequency options from 1 to 12', async () => {
    const user = userEvent.setup();

    render(
      <LineItemsTable 
        lineItems={mockLineItems}
        onFrequencyChange={mockOnFrequencyChange}
      />
    );

    const firstDropdown = screen.getAllByRole('combobox')[0];

    // Check all options exist
    for (let i = 1; i <= 12; i++) {
      const option = firstDropdown.querySelector(`option[value="${i}"]`);
      expect(option).toBeInTheDocument();
      expect(option).toHaveTextContent(i.toString());
    }

    // Verify no empty option exists
    const emptyOption = firstDropdown.querySelector('option[value=""]');
    expect(emptyOption).not.toBeInTheDocument();
  });

  it('formats money correctly', () => {
    const itemsWithVariousPrices: LineItem[] = [
      {
        id: 'rec1',
        service: 'Test Service',
        alaCarteRate: 1234.56,
        handldRate: 999.99,
        quoteId: 'Q-001',
      },
      {
        id: 'rec2',
        service: 'Service with undefined',
        alaCarteRate: undefined as any,
        handldRate: undefined as any,
        quoteId: 'Q-001',
      },
    ];

    render(
      <LineItemsTable lineItems={itemsWithVariousPrices} />
    );

    // Check formatted prices
    expect(screen.getByText('$1,235')).toBeInTheDocument();
    expect(screen.getByText('$1,000')).toBeInTheDocument();

    // Check undefined prices show as dash
    expect(screen.getAllByText('-')).toHaveLength(2);
  });
});

