// components/ui/loading-screen.tsx
'use client';

import { BrandSpinner } from './brand-spinner';
import { Logo } from './logo';

interface LoadingScreenProps {
  message?: string;
}

export function LoadingScreen({ message = "Loading your quote..." }: LoadingScreenProps) {
  return (
    <div className="min-h-screen flex items-center justify-center bg-brand-cream">
      <div className="flex flex-col items-center space-y-6">
        {/* Logo with spinner around it */}
        <div className="relative flex items-center justify-center">
          {/* Brand spinner */}
          <BrandSpinner size={128} className="absolute" />

          {/* Logo in center */}
          <Logo size={80} className="z-10" />
        </div>

        {/* Loading message */}
        <div className="text-center">
          <p className="text-brand-navy text-lg font-medium">{message}</p>
        </div>
      </div>
    </div>
  );
}

